#!/usr/bin/env python3
from pathlib import Path

ROOT = Path('.')

def rep(path, old, new, count=1):
    p = ROOT / path
    s = p.read_text(encoding='utf-8')
    if old not in s:
        raise SystemExit(f'missing token in {path}: {old[:180]}')
    p.write_text(s.replace(old, new, count), encoding='utf-8')

# RC14 is applied after RC13. Preserve RC12 Bluetooth runtime and RC13 GPS transport logic.
for path in ['buildsrc/store-app/build.gradle.kts','buildsrc/employee-app/build.gradle.kts']:
    p = ROOT / path
    s = p.read_text(encoding='utf-8')
    s = s.replace('versionCode = 103', 'versionCode = 104')
    s = s.replace('versionName = "2.0.0-RC13"', 'versionName = "2.0.0-RC14"')
    p.write_text(s, encoding='utf-8')

main = 'buildsrc/store-app/src/main/java/com/attendpro/store/MainActivity.kt'

